using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace KvPwSafe.PasskeyProvider;

internal static class Provider
{
    // COM class of the plugin authenticator (also in AppxManifest.xml).
    public static Guid Clsid = new("829d1c65-49a0-41a5-8b6b-ae387f64db07");
    public const string Name = "Keevault";
    public const string PluginRpId = "kvpwsafe.local";

    // authenticatorGetInfo: {1: ["FIDO_2_0","FIDO_2_1"], 3: AAGUID, 4: {rk, up, uv}, 9: ["internal"], 10: [ES256]}
    // (generated by extension/core/ctap.js authenticatorInfo()).
    public const string AuthenticatorInfoHex =
        "a50182684649444f5f325f30684649444f5f325f3103506b7670772d73616665a1c3e5f70d2b9e04a362726bf5627570f5627576f509" +
        "8168696e7465726e616c0a81a263616c672664747970656a7075626c69632d6b6579";

    public const string LogoSvg =
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 128 128\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">" +
        "<stop offset=\"0\" stop-color=\"#248ce6\"/><stop offset=\"1\" stop-color=\"#0b488c\"/></linearGradient></defs>" +
        "<rect x=\"4\" y=\"4\" width=\"120\" height=\"120\" rx=\"28\" fill=\"url(#g)\"/>" +
        "<path d=\"M64 20 102 33v27c0 26-16 41-38 50-22-9-38-24-38-50V33z\" fill=\"#fff\"/>" +
        "<circle cx=\"64\" cy=\"55\" r=\"13\" fill=\"#0f6cbd\"/><path d=\"M57 60h14l4 30H53z\" fill=\"#0f6cbd\"/></svg>";
}

internal static class Program
{
    private static int _active;
    private static DateTime _lastActivity = DateTime.UtcNow;

    public static void Activity(int delta)
    {
        Interlocked.Add(ref _active, delta);
        _lastActivity = DateTime.UtcNow;
    }

    [MTAThread]
    private static int Main(string[] args)
    {
        var mode = args.FirstOrDefault() ?? "";
        try
        {
            return mode switch
            {
                "-PluginActivated" => RunServer(),
                "--register" => Print(Register()),
                "--unregister" => Print(Unregister()),
                "--status" => Print(Status()),
                "--sync" => Print(SyncCredentials(Console.In.ReadToEnd())),
                _ => Print(new JsonObject { ["usage"] = "--register | --unregister | --status | --sync (JSON on stdin)" }),
            };
        }
        catch (Exception e)
        {
            Log.Write($"{mode}: {e}");
            return Print(new JsonObject { ["error"] = e.Message, ["hresult"] = $"0x{e.HResult:X8}" }, 1);
        }
    }

    private static int Print(JsonObject result, int code = 0)
    {
        Console.Out.Write(result.ToJsonString());
        Console.Out.Flush();
        return code;
    }

    /// <summary>COM activation by Windows: serve until idle.</summary>
    private static int RunServer()
    {
        Log.Write("activated by Windows");
        var clsid = Provider.Clsid;
        var hr = Native.CoRegisterClassObject(ref clsid, new PluginFactory(), Native.CLSCTX_LOCAL_SERVER, Native.REGCLS_MULTIPLEUSE, out var cookie);
        if (hr != 0)
        {
            Log.Write($"CoRegisterClassObject failed 0x{hr:X8}");
            return hr;
        }
        while (Volatile.Read(ref _active) > 0 || DateTime.UtcNow - _lastActivity < TimeSpan.FromMinutes(5)) Thread.Sleep(1000);
        Native.CoRevokeClassObject(cookie);
        Log.Write("idle, exiting");
        return 0;
    }

    private static JsonObject Status()
    {
        var clsid = Provider.Clsid;
        var hr = Native.WebAuthNPluginGetAuthenticatorState(ref clsid, out var state);
        return new JsonObject { ["registered"] = hr == 0, ["enabled"] = hr == 0 && state == 1, ["hresult"] = $"0x{hr:X8}" };
    }

    private static JsonObject Register()
    {
        using var arena = new Arena();
        var info = Convert.FromHexString(Provider.AuthenticatorInfoHex);
        var logo = Convert.ToBase64String(Encoding.UTF8.GetBytes(Provider.LogoSvg));
        var clsid = arena.Bytes(Provider.Clsid.ToByteArray());
        // WEBAUTHN_PLUGIN_ADD_AUTHENTICATOR_OPTIONS (x64): name 0, rclsid 8, rpId 16, light 24, dark 32, cbInfo 40, pbInfo 48, cRpIds 56, ppRpIds 64
        var options = arena.Zeroed(72);
        Marshal.WriteIntPtr(options, 0, arena.String(Provider.Name));
        Marshal.WriteIntPtr(options, 8, clsid);
        // Documented as optional, but Windows 11 25H2 rejects the call without it (NTE_INVALID_PARAMETER).
        Marshal.WriteIntPtr(options, 16, arena.String(Provider.PluginRpId));
        Marshal.WriteIntPtr(options, 24, arena.String(logo));
        Marshal.WriteIntPtr(options, 32, arena.String(logo));
        Marshal.WriteInt32(options, 40, info.Length);
        Marshal.WriteIntPtr(options, 48, arena.Bytes(info));
        var hr = Native.WebAuthNPluginAddAuthenticator(options, out var response);
        if (response != IntPtr.Zero) Native.WebAuthNPluginFreeAddAuthenticatorResponse(response);
        // NTE_EXISTS: already registered.
        var ok = hr == 0 || hr == unchecked((int)0x8009000F);
        return new JsonObject { ["registered"] = ok, ["hresult"] = $"0x{hr:X8}", ["status"] = Status() };
    }

    private static JsonObject Unregister()
    {
        var clsid = Provider.Clsid;
        var hr = Native.WebAuthNPluginRemoveAuthenticator(ref clsid);
        return new JsonObject { ["removed"] = hr == 0, ["hresult"] = $"0x{hr:X8}" };
    }

    private sealed record CredentialInfo(string CredentialId, string RpId, string RpName, string UserId, string UserName, string UserDisplayName);

    private static byte[] FromB64Url(string s)
    {
        s = s.Replace('-', '+').Replace('_', '/');
        return Convert.FromBase64String(s + new string('=', (4 - s.Length % 4) % 4));
    }

    /// <summary>Replaces the credential metadata Windows shows in its passkey picker (no keys, only names).</summary>
    private static JsonObject SyncCredentials(string json)
    {
        var list = JsonSerializer.Deserialize<List<CredentialInfo>>(json, Json.Options) ?? new();
        var clsid = Provider.Clsid;
        var hrRemove = Native.WebAuthNPluginAuthenticatorRemoveAllCredentials(ref clsid);
        if (list.Count == 0) return new JsonObject { ["synced"] = 0, ["hresult"] = $"0x{hrRemove:X8}" };
        using var arena = new Arena();
        // WEBAUTHN_PLUGIN_CREDENTIAL_DETAILS (x64): cbId 0, pbId 8, rpId 16, rpName 24, cbUserId 32, pbUserId 40, userName 48, displayName 56
        const int size = 64;
        var array = arena.Zeroed(size * list.Count);
        for (var i = 0; i < list.Count; i++)
        {
            var c = list[i];
            var p = array + i * size;
            var id = FromB64Url(c.CredentialId);
            var user = FromB64Url(c.UserId);
            Marshal.WriteInt32(p, 0, id.Length);
            Marshal.WriteIntPtr(p, 8, arena.Bytes(id));
            Marshal.WriteIntPtr(p, 16, arena.String(c.RpId));
            Marshal.WriteIntPtr(p, 24, arena.String(string.IsNullOrEmpty(c.RpName) ? c.RpId : c.RpName));
            Marshal.WriteInt32(p, 32, user.Length);
            Marshal.WriteIntPtr(p, 40, arena.Bytes(user));
            Marshal.WriteIntPtr(p, 48, arena.String(c.UserName));
            Marshal.WriteIntPtr(p, 56, arena.String(string.IsNullOrEmpty(c.UserDisplayName) ? c.UserName : c.UserDisplayName));
        }
        var hr = Native.WebAuthNPluginAuthenticatorAddCredentials(ref clsid, (uint)list.Count, array);
        return new JsonObject { ["synced"] = hr == 0 ? list.Count : 0, ["hresult"] = $"0x{hr:X8}" };
    }
}
